// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, bool shouldRevert) public {
        amount = bound(amount, 1, 1 ether);

        ReverterOrAcceptor helper = new ReverterOrAcceptor(shouldRevert);

        vm.deal(address(c), amount);

        bool ok;
        try c.sendMoney(address(helper), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!shouldRevert || (!ok));
    }
}

contract ReverterOrAcceptor {
    bool public willRevert;
    constructor(bool _willRevert) payable { willRevert = _willRevert; }
    receive() external payable {
        if (willRevert) revert("receive revert");
    }
    fallback() external payable {
        if (willRevert) revert("fallback revert");
    }
}
